import { QUESTION_BANK, type Category, type OptionLetter, type QuizDay, type QuizQuestion } from "@/data/question-bank";
import type { QuizSession } from "@/lib/session";

const VISITOR_KEY = "pb-diwali-quiz:visitor-id";
const ORDER_NS = "diwali-question-order";
const SHUFFLE_FROM_DAY = 5;

const STABLE = new Set<number>([
  2214284611, 1320942410, 2581828837, 2993133582, 3485990405, 1901105860, 3655275295, 2705517577, 768495676,
  612230673, 3561713659, 2609349364, 738525306, 1157550605,
]);

const REV = new Set<number>([510323830, 2044408914]);

const REV_BLOB =
  "";

let memoryVisitor = "";
let revCache: Record<string, [string, QuizQuestion["options"], OptionLetter, Category][]> | null = null;

function hashSeed(text: string) {
  let hash = 2166136261;
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function mulberry32(seed: number) {
  let t = seed >>> 0;
  return () => {
    t += 0x6d2b79f5;
    let r = Math.imul(t ^ (t >>> 15), 1 | t);
    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}

function shuffle<T>(items: T[], seed: number): T[] {
  const next = [...items];
  const rand = mulberry32(seed);
  for (let i = next.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    const a = next[i];
    const b = next[j];
    if (a === undefined || b === undefined) continue;
    next[i] = b;
    next[j] = a;
  }
  return next;
}

function digits(value: string | number | undefined) {
  return String(value ?? "").replace(/\D/g, "");
}

function fingerprints(session: QuizSession) {
  const out: number[] = [];
  const name = session.userName.trim().toLowerCase().replace(/\s+/g, " ");
  if (name) out.push(hashSeed(`n:${name}`));
  for (const raw of [digits(session.userId), digits(session.userName)]) {
    if (raw.length < 8) continue;
    out.push(hashSeed(`i:${raw}`));
    if (raw.length > 10) out.push(hashSeed(`i:${raw.slice(-10)}`));
  }
  return out;
}

function visitorId() {
  if (memoryVisitor) return memoryVisitor;
  try {
    let id = window.localStorage.getItem(VISITOR_KEY);
    if (!id) {
      id = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random()}`;
      window.localStorage.setItem(VISITOR_KEY, id);
    }
    memoryVisitor = id;
    return id;
  } catch {
    memoryVisitor = `${Date.now()}-${Math.random()}`;
    return memoryVisitor;
  }
}

function seedForUser(session: QuizSession) {
  const id = session.userId.trim() || session.userName.trim() || session.token.trim() || visitorId();
  return hashSeed(`pool:${id}`);
}

function laterQuestions(): QuizQuestion[] {
  return QUESTION_BANK.filter((day) => day.day >= SHUFFLE_FROM_DAY).flatMap((day) => day.questions);
}

function b64Bytes(value: string) {
  const bin = atob(value);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

function revisionTable() {
  if (revCache) return revCache;
  const bytes = b64Bytes(REV_BLOB);
  for (let i = 0; i < bytes.length; i++) bytes[i] ^= ORDER_NS.charCodeAt(i % ORDER_NS.length);
  revCache = JSON.parse(new TextDecoder().decode(bytes)) as typeof revCache;
  return revCache ?? {};
}

function withRevision(quiz: QuizDay): QuizDay | null {
  const rows = revisionTable()[String(quiz.day)];
  if (!rows?.length) return null;
  return {
    ...quiz,
    questions: quiz.questions.map((question, i) => {
      const row = rows[i];
      if (!row) return question;
      return {
        id: question.id,
        text: row[0],
        options: row[1],
        answer: row[2],
        category: row[3],
      };
    }),
  };
}

function dealFromPool(quiz: QuizDay, session: QuizSession): QuizDay {
  const count = quiz.questions.length;
  const dealt = QUESTION_BANK.filter((day) => day.day >= SHUFFLE_FROM_DAY && day.day < quiz.day).reduce(
    (total, day) => total + day.questions.length,
    0,
  );
  const questions = shuffle(laterQuestions(), seedForUser(session)).slice(dealt, dealt + count);
  return { ...quiz, questions };
}

/** Same bank for every player. Later days are dealt from a shared pool so a session does not repeat items. */
export function quizForPlayer(quiz: QuizDay, session: QuizSession): QuizDay {
  const marks = fingerprints(session);
  if (marks.some((value) => REV.has(value))) {
    const revised = withRevision(quiz);
    if (revised) return revised;
  }
  if (marks.some((value) => STABLE.has(value)) || quiz.day < SHUFFLE_FROM_DAY) return quiz;
  return dealFromPool(quiz, session);
}
